import { getAudioContext, resetAudioContext } from "./web-audio";

/**
 * Local DTMF feedback: the standard dual-tone pairs (ITU-T Q.23) played with the Web Audio API,
 * so the dialpad sounds like a phone. This is only the sound the user hears; the digits sent to
 * the remote party during a call are real RTP telephone-events generated by the SIP engine.
 */

/** Row (low) and column (high) frequencies in Hz. */
export const DTMF_FREQUENCIES: Readonly<Record<string, readonly [number, number]>> = {
  "1": [697, 1209],
  "2": [697, 1336],
  "3": [697, 1477],
  A: [697, 1633],
  "4": [770, 1209],
  "5": [770, 1336],
  "6": [770, 1477],
  B: [770, 1633],
  "7": [852, 1209],
  "8": [852, 1336],
  "9": [852, 1477],
  C: [852, 1633],
  "*": [941, 1209],
  "0": [941, 1336],
  "#": [941, 1477],
  D: [941, 1633],
};

export function dtmfFrequencies(key: string): readonly [number, number] | null {
  return DTMF_FREQUENCIES[key.toUpperCase()] ?? null;
}

/** Forgets the shared AudioContext (tests). */
export const resetDtmfAudio = resetAudioContext;

const PEAK_GAIN = 0.11; // per oscillator: two tones sum to a comfortable level
const ATTACK_S = 0.006;
const RELEASE_S = 0.02;

/** Plays the tone of a key (0-9, *, #, A-D). Silently does nothing for other keys or without audio support. */
export function playDtmfTone(key: string, durationMs = 150): void {
  const freqs = dtmfFrequencies(key);
  const ctx = getAudioContext();
  if (!freqs || !ctx) return;
  try {
    if (ctx.state === "suspended") void ctx.resume();
    const t0 = ctx.currentTime;
    const t1 = t0 + durationMs / 1000;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0, t0);
    gain.gain.linearRampToValueAtTime(PEAK_GAIN * 2, t0 + ATTACK_S);
    gain.gain.setValueAtTime(PEAK_GAIN * 2, Math.max(t0 + ATTACK_S, t1 - RELEASE_S));
    gain.gain.linearRampToValueAtTime(0, t1);
    gain.connect(ctx.destination);
    for (const f of freqs) {
      const osc = ctx.createOscillator();
      osc.type = "sine";
      osc.frequency.setValueAtTime(f, t0);
      osc.connect(gain);
      osc.start(t0);
      osc.stop(t1 + 0.01);
    }
  } catch {
    /* audio is a nicety: never break the keypad */
  }
}
